import sys

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        Q = int(input[ptr])
        ptr += 1
        S = set()
        E, O = 0, 0
        for __ in range(Q):
            X = int(input[ptr])
            ptr += 1
            new_elements = []
            if X not in S:
                new_elements.append(X)
                for y in S:
                    xor = y ^ X
                    if xor not in S:
                        new_elements.append(xor)
            for num in new_elements:
                S.add(num)
                if bin(num).count('1') % 2 == 0:
                    E += 1
                else:
                    O += 1
            print(E, O)

solve()
